import java.util.*;

class Solution {
  public int maxVacationDays(int[][] flights, int[][] days) {
    int n = flights.length, weeks = days[0].length;
    int[] best = new int[n]; // best[c]: most vacation days so far ending the week in city c
    Arrays.fill(best, Integer.MIN_VALUE);
    best[0] = 0;
    for (int w = 0; w < weeks; w++) {
      int[] next = new int[n];
      Arrays.fill(next, Integer.MIN_VALUE);
      for (int to = 0; to < n; to++)
        for (int from = 0; from < n; from++)
          if (best[from] != Integer.MIN_VALUE && (from == to || flights[from][to] == 1))
            next[to] = Math.max(next[to], best[from] + days[to][w]);
      best = next;
    }
    int res = 0;
    for (int b : best) res = Math.max(res, b);
    return res;
  }
}
